- 2 int data; 3 struct element *next; 4 }; 5

- 6 struct element *list = 0;

- 7 8 void 9 push(int data)

- 10 {

- 11 struct element *l;

- 12

- 13 l = malloc(sizeof *l); 14 l->data = data; 15 l->next = list; 16 list = l;

